insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('1df309dc-4cad-5393-b532-525f091910cf', 'wg6-writing-with-evidence-p08', (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null,
        '6-8', $q$Draft: Why Scientists Still Sketch$q$, $q$(1) Olivia Brennan's article "The Sketchbook Scientist" explains why some scientists still draw what they study, even though cameras are everywhere. (2) ____. (3) Brennan describes a scientist who drew the same leaf every day for a week. (4) By the third day, the scientist noticed tiny hairs on the stem that she had missed in her photographs. (5) This example shows that drawing makes a person look slowly and carefully.

(6) ____, Brennan explains that drawings help scientists remember what they see. (7) She writes that students who sketched insects in one class could describe them better a month later than students who only took photos. (8) Taking photos with a phone is easy and fast. (9) Brennan suggests that the act of drawing helps lock details into memory.

(10) In my opinion, everyone should take an art class.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
